revoke all on function core.rt_can_read(text, text) from public, anon, authenticated;
grant execute on function core.rt_can_read(text, text) to service_role;

-- the person signed in now: may they read this place?
create or replace function core.rt_may_read(p_path text) returns boolean language plpgsql volatile security definer set search_path = core, public as $$
begin
  if auth.role() = 'service_role' then return true; end if;
  return core.rt_can_read(core.me_email(), p_path);
end $$;
revoke all on function core.rt_may_read(text) from public;
grant execute on function core.rt_may_read(text) to anon, authenticated, service_role;

-- for the proof (rights-proof.js): many answers in one call — [{ e, p, v, w }] → [true/false …] (w = a save, else a read)
create or replace function core.rt_rights_many(p_cases jsonb) returns jsonb language sql volatile security definer set search_path = core, public as $$
  select coalesce(jsonb_agg(case when (c->>'w')::boolean then core.rt_can_save(c->>'e', c->>'p', c->'v') else core.rt_can_read(c->>'e', c->>'p') end order by i), '[]'::jsonb)
    from jsonb_array_elements(p_cases) with ordinality t(c, i)
$$;
revoke all on function core.rt_rights_many(jsonb) from public, anon, authenticated;
grant execute on function core.rt_rights_many(jsonb) to service_role;

-- SAVES: Firebase's rules decide, change by change (a vendor may now save its own branch). Firestore documents (fs/…) keep
-- their own rule here: staff only, access rights by an admin, settings with API keys never.
create or replace function core.rt_save(p_changes jsonb, p_screen text default null) returns int
language plpgsql security definer set search_path = core, public as $$
declare n int; bad text; em text := core.me_email(); svc boolean := auth.role() = 'service_role';
begin
  if em is null and not svc then raise exception 'rt_save: not an ERP sign-in'; end if;
  if jsonb_typeof(p_changes) <> 'array' then raise exception 'rt_save: changes must be a list'; end if;
  if jsonb_array_length(p_changes) > 2000 then raise exception 'rt_save: at most 2,000 changes at once'; end if;
  if octet_length(p_changes::text) > 8000000 then raise exception 'rt_save: at most 8 MB at once'; end if;
  select c->>'p' into bad from jsonb_array_elements(p_changes) c where trim(both '/' from c->>'p') ~ '^fs/config(/|$)' limit 1;
  if bad is not null then raise exception 'rt_save: settings with API keys are not saved here (%)', bad; end if;
  if not svc then
    select c->>'p' into bad from jsonb_array_elements(p_changes) c
     where trim(both '/' from c->>'p') ~ '^fs(/|$)' and (not core.rt_reader() or (trim(both '/' from c->>'p') ~ '^fs/perms(/|$)' and not core.rt_admin())) limit 1;
    if bad is not null then raise exception 'rt_save: permission denied — % (Firestore: staff only; access rights by an admin)', bad; end if;
    select c->>'p' into bad from jsonb_array_elements(p_changes) c
     where trim(both '/' from c->>'p') !~ '^fs(/|$)'
       and not core.rt_can_save(em, c->>'p', case when c->'v' = 'null'::jsonb or c->>'k' = 'delete' then null else c->'v' end) limit 1;
    if bad is not null then raise exception 'rt_save: permission denied — % may not change % (the same rule as Firebase)', em, bad; end if;
  end if;
  insert into core.sync_inbox (saved_at, email, kind, path, value, screen)
  select case when c->>'t' ~ '^\d{4}-\d{2}-\d{2}' then (c->>'t')::timestamptz end,
         coalesce(em, 'server'),
         c->>'k', trim(both '/' from c->>'p'), case when c->'v' = 'null'::jsonb then null else c->'v' end,
         left('test link · ' || coalesce(p_screen, ''), 80)
    from jsonb_array_elements(p_changes) c
   where c->>'k' in ('put', 'patch', 'delete') and coalesce(trim(both '/' from c->>'p'), '') <> '';
  get diagnostics n = row_count;
  if n > 0 then perform core.sync_now(); end if;
  return n;
end $$;
revoke all on function core.rt_save(jsonb, text) from public;
grant execute on function core.rt_save(jsonb, text) to anon, authenticated, service_role;

create or replace function core.rt_cas(p_path text, p_expect jsonb, p_next jsonb) returns text
language plpgsql security definer set search_path = core, public as $$
declare cur jsonb;
begin
  if core.me_email() is null and auth.role() is distinct from 'service_role' then raise exception 'rt_cas: not an ERP sign-in'; end if;
  perform pg_advisory_xact_lock(hashtext('rt_cas:' || p_path));
  perform core.sync_now();
  cur := core.rt_value(p_path);
  if coalesce(cur, 'null'::jsonb) is distinct from coalesce(p_expect, 'null'::jsonb) then return 'changed'; end if;
  perform core.rt_save(jsonb_build_array(jsonb_build_object('k', 'put', 'p', trim(both '/' from p_path), 'v', p_next,
    't', to_char(now() at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))), 'compare-and-set');
  return '';
end $$;
revoke all on function core.rt_cas(text, jsonb, jsonb) from public;
grant execute on function core.rt_cas(text, jsonb, jsonb) to anon, authenticated, service_role;

-- READS: each read door asks Firebase's read rule for its own path (was: any ERP sign-in reads everything)
do $do$ declare f record; d text; done int := 0;
begin
  for f in select p.oid, p.proname, (select string_agg(a, ',') from unnest(p.proargnames) a) args
             from pg_proc p join pg_namespace ns on ns.oid = p.pronamespace
            where ns.nspname = 'core' and p.proname in ('rt_get', 'rt_get_json', 'rt_get_text', 'rt_get_v', 'rt_changes', 'rt_list_upto') loop
    d := pg_get_functiondef(f.oid);
    if position('core.rt_reader()' in d) = 0 then continue; end if;
    d := replace(d, 'if not core.rt_reader() then', 'if not core.rt_may_read(' || case when f.args like 'p_reg%' then 'p_reg' else 'p_path' end || ') then');
    execute d; done := done + 1;
  end loop;
  if done < 6 then raise exception 'read doors: % of 6 changed', done; end if;
  -- Firestore: anybody signed in reads their OWN rights document (perms/<email>), as firestore.rules allows — a vendor too
  d := pg_get_functiondef('core.fs_get(text, text)'::regprocedure);
  if position('core.rt_reader()' in d) > 0 and position('p_coll = ''perms''' in d) = 0 then
    d := replace(d, 'if not core.rt_reader() then', 'if not (core.rt_reader() or (p_coll = ''perms'' and lower(p_id) = lower(core.me_email()))) then');
    execute d;
  end if;
end $do$;

-- the list files: each file by the read rule of its list (the manifest: any ERP sign-in)
drop policy if exists "erp lists: ERP readers" on storage.objects;
create policy "erp lists: ERP readers" on storage.objects for select to anon, authenticated
  using (bucket_id = 'erp-lists' and (case when name = 'manifest.json' then core.rt_reader() else core.rt_may_read(regexp_replace(name, '\.json$', '')) end));

notify pgrst, 'reload schema';
select case when has_function_privilege('authenticated', 'core.rt_may_read(text)', 'execute')
             and not has_function_privilege('anon', 'core.rt_can_save(text, text, jsonb)', 'execute')
             and position('rt_may_read' in pg_get_functiondef('core.rt_get(text, text, jsonb, integer)'::regprocedure)) > 0
            then 'PASS' else 'FAIL' end as result;
